-- 今日任务素材初始化：技术内容、英语新词、复习知识、行动素材各 20 条。
-- 可重复执行：同一 ID 会更新为已发布/可用状态。
CREATE TABLE IF NOT EXISTS learning_content (
  id CHAR(32) NOT NULL PRIMARY KEY, content_type VARCHAR(16) NOT NULL, topic_id CHAR(32) NULL,
  title VARCHAR(100) NOT NULL, difficulty VARCHAR(32) NOT NULL DEFAULT 'intro', estimated_seconds INT NOT NULL,
  state VARCHAR(16) NOT NULL DEFAULT 'published', sort_no INT NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  KEY idx_learning_content_pick (content_type, state, difficulty, sort_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS knowledge_item (
  id CHAR(32) NOT NULL PRIMARY KEY, title VARCHAR(100) NOT NULL, estimated_seconds INT NOT NULL, next_review_date DATE NOT NULL,
  state VARCHAR(16) NOT NULL DEFAULT 'active', sort_no INT NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  KEY idx_knowledge_item_review (state, next_review_date, sort_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS weekly_action (
  id CHAR(32) NOT NULL PRIMARY KEY, title VARCHAR(100) NOT NULL, estimated_seconds INT NOT NULL,
  state VARCHAR(16) NOT NULL DEFAULT 'active', sort_no INT NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  KEY idx_weekly_action_pick (state, sort_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

